import { useEffect } from "react";
import { useTranslation } from "react-i18next";
import { useLocation } from "react-router-dom";

import { SITE_CONTACTS } from "../../config/site";
import { findRoute, getSiteOrigin, OG_IMAGE_PATH, OG_LOCALES, SITE_NAME } from "../../config/seo";

/**
 * Keeps <head> metadata in sync while the user navigates inside the SPA or
 * switches language. The initial HTML of every page already contains the same
 * tags (generated by scripts/postbuild.mjs), so crawlers that do not execute
 * JavaScript still get correct titles, descriptions and structured data.
 */

const setMeta = (attribute: "name" | "property", key: string, content: string) => {
  let element = document.head.querySelector<HTMLMetaElement>(`meta[${attribute}="${key}"]`);
  if (!element) {
    element = document.createElement("meta");
    element.setAttribute(attribute, key);
    document.head.appendChild(element);
  }
  element.setAttribute("content", content);
};

const setCanonical = (href: string | null) => {
  let canonical = document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');
  if (!href) {
    canonical?.remove();
    return;
  }
  if (!canonical) {
    canonical = document.createElement("link");
    canonical.rel = "canonical";
    document.head.appendChild(canonical);
  }
  canonical.href = href;
};

const PageSEO = () => {
  const { pathname } = useLocation();
  const { t, i18n } = useTranslation();
  const language = (i18n.resolvedLanguage || i18n.language || "ru").split("-")[0];

  useEffect(() => {
    const route = findRoute(pathname);
    const origin = getSiteOrigin();
    const seoKey = route ? route.key : "notFound";
    const title = t(`seo.${seoKey}.title`);
    const description = t(`seo.${seoKey}.description`);
    const canonicalUrl = route ? `${origin}${route.path}` : null;
    const imageUrl = `${origin}${OG_IMAGE_PATH}`;

    document.documentElement.lang = language;
    document.title = title;

    setMeta("name", "description", description);
    setMeta("name", "robots", route ? "index, follow, max-image-preview:large" : "noindex, follow");
    setMeta("property", "og:type", "website");
    setMeta("property", "og:site_name", SITE_NAME);
    setMeta("property", "og:locale", OG_LOCALES[language] ?? "ru_RU");
    setMeta("property", "og:title", title);
    setMeta("property", "og:description", description);
    setMeta("property", "og:url", canonicalUrl ?? `${origin}${pathname}`);
    setMeta("property", "og:image", imageUrl);
    setMeta("name", "twitter:card", "summary_large_image");
    setMeta("name", "twitter:title", title);
    setMeta("name", "twitter:description", description);
    setMeta("name", "twitter:image", imageUrl);
    setCanonical(canonicalUrl);

    const graph: Record<string, unknown>[] = [
      {
        "@type": "Organization",
        "@id": `${origin}/#organization`,
        name: SITE_NAME,
        url: `${origin}/`,
        logo: `${origin}/icon-512.png`,
        image: imageUrl,
        email: SITE_CONTACTS.email,
        telephone: SITE_CONTACTS.phones[0],
        contactPoint: SITE_CONTACTS.phones.map((telephone) => ({
          "@type": "ContactPoint",
          telephone,
          email: SITE_CONTACTS.email,
          contactType: "customer support",
          areaServed: "KZ",
          availableLanguage: ["ru", "kk", "en"],
        })),
      },
      {
        "@type": "WebSite",
        "@id": `${origin}/#website`,
        url: `${origin}/`,
        name: SITE_NAME,
        publisher: { "@id": `${origin}/#organization` },
        inLanguage: language,
      },
    ];

    if (route && canonicalUrl) {
      graph.push({
        "@type": "WebPage",
        "@id": `${canonicalUrl}#webpage`,
        url: canonicalUrl,
        name: title,
        description,
        inLanguage: language,
        isPartOf: { "@id": `${origin}/#website` },
      });
    }

    if (route && route.path !== "/" && canonicalUrl) {
      graph.push({
        "@type": "BreadcrumbList",
        itemListElement: [
          { "@type": "ListItem", position: 1, name: t("nav.home"), item: `${origin}/` },
          { "@type": "ListItem", position: 2, name: t(`nav.${route.key}`), item: canonicalUrl },
        ],
      });
    }

    let script = document.getElementById("structured-data") as HTMLScriptElement | null;
    if (!script) {
      script = document.createElement("script");
      script.id = "structured-data";
      script.type = "application/ld+json";
      document.head.appendChild(script);
    }
    script.textContent = JSON.stringify({ "@context": "https://schema.org", "@graph": graph });
  }, [language, pathname, t]);

  return null;
};

export default PageSEO;
